<?php\n/**\n * Plugin Name: Ashler POS File Installer\n * Description: Lets an authenticated Ashler Trends POS owner upload a local plugin ZIP to this WordPress site.\n * Version: 1.0.0\n * Requires at least: 5.6\n * Requires PHP: 7.4\n * Author: Ashler Trends\n * License: GPL-2.0-or-later\n */\n\nif ( ! defined( 'ABSPATH' ) ) {\n	exit;\n}\n\nadd_action( 'rest_api_init', function () {\n	register_rest_route(\n		'ashler-pos/v1',\n		'/status',\n		array(\n			'methods'             => WP_REST_Server::READABLE,\n			'permission_callback' => function () {\n				return current_user_can( 'install_plugins' );\n			},\n			'callback'            => function () {\n				return rest_ensure_response( array( 'ready' => true, 'version' => '1.0.0' ) );\n			},\n		)\n	);\n\n	register_rest_route(\n		'ashler-pos/v1',\n		'/install-plugin',\n		array(\n			'methods'             => WP_REST_Server::CREATABLE,\n			'permission_callback' => function () {\n				return current_user_can( 'install_plugins' );\n			},\n			'callback'            => 'ashler_pos_install_plugin_zip',\n		)\n	);\n} );\n\nfunction ashler_pos_install_plugin_zip( WP_REST_Request $request ) {\n	$files = $request->get_file_params();\n	if ( empty( $files['pluginZip'] ) || ! is_array( $files['pluginZip'] ) ) {\n		return new WP_Error( 'ashler_pos_missing_zip', 'Choose a plugin ZIP file.', array( 'status' => 400 ) );\n	}\n\n	$file = $files['pluginZip'];\n	if ( ! empty( $file['error'] ) || empty( $file['tmp_name'] ) || ! is_uploaded_file( $file['tmp_name'] ) ) {\n		return new WP_Error( 'ashler_pos_upload_failed', 'WordPress could not receive the uploaded file.', array( 'status' => 400 ) );\n	}\n\n	if ( empty( $file['size'] ) || $file['size'] > 20 * 1024 * 1024 ) {\n		return new WP_Error( 'ashler_pos_zip_size', 'Plugin ZIP files must be smaller than 20 MB.', array( 'status' => 413 ) );\n	}\n\n	$filename = sanitize_file_name( $file['name'] );\n	if ( strtolower( pathinfo( $filename, PATHINFO_EXTENSION ) ) !== 'zip' ) {\n		return new WP_Error( 'ashler_pos_zip_type', 'Choose a .zip plugin file.', array( 'status' => 400 ) );\n	}\n\n	$handle = fopen( $file['tmp_name'], 'rb' );\n	$signature = $handle ? fread( $handle, 4 ) : '';\n	if ( $handle ) {\n		fclose( $handle );\n	}\n	if ( ! in_array( $signature, array( "PK\x03\x04", "PK\x05\x06", "PK\x07\x08" ), true ) ) {\n		return new WP_Error( 'ashler_pos_invalid_zip', 'The uploaded file is not a valid ZIP archive.', array( 'status' => 400 ) );\n	}\n\n	require_once ABSPATH . 'wp-admin/includes/file.php';\n	require_once ABSPATH . 'wp-admin/includes/plugin.php';\n	require_once ABSPATH . 'wp-admin/includes/class-wp-upgrader.php';\n	require_once ABSPATH . 'wp-admin/includes/class-wp-ajax-upgrader-skin.php';\n\n	$skin = new WP_Ajax_Upgrader_Skin();\n	$upgrader = new Plugin_Upgrader( $skin );\n	$result = $upgrader->install( $file['tmp_name'] );\n	if ( is_wp_error( $result ) ) {\n		return new WP_Error( 'ashler_pos_install_failed', wp_strip_all_tags( $result->get_error_message() ), array( 'status' => 400 ) );\n	}\n	if ( is_null( $result ) || $skin->get_errors()->has_errors() ) {\n		$message = $skin->get_errors()->has_errors() ? $skin->get_errors()->get_error_message() : 'WordPress could not write the plugin files. Check filesystem permissions.';\n		return new WP_Error( 'ashler_pos_install_failed', wp_strip_all_tags( $message ), array( 'status' => 500 ) );\n	}\n\n	$plugin_file = $upgrader->plugin_info();\n	if ( ! $plugin_file || ! file_exists( WP_PLUGIN_DIR . '/' . $plugin_file ) ) {\n		return new WP_Error( 'ashler_pos_plugin_not_found', 'WordPress installed the ZIP but could not identify the plugin entry file.', array( 'status' => 500 ) );\n	}\n\n	$activation = activate_plugin( $plugin_file, '', false, false );\n	if ( is_wp_error( $activation ) ) {\n		return new WP_Error( 'ashler_pos_activation_failed', wp_strip_all_tags( $activation->get_error_message() ), array( 'status' => 400 ) );\n	}\n\n	$data = get_plugin_data( WP_PLUGIN_DIR . '/' . $plugin_file, false, false );\n	return rest_ensure_response(\n		array(\n			'plugin'  => $plugin_file,\n			'name'    => sanitize_text_field( $data['Name'] ),\n			'version' => sanitize_text_field( $data['Version'] ),\n			'status'  => 'active',\n		)\n	);\n}\n